// Valida el archivo que llego por el formulario y lo normaliza.
const it = $input.first();
const bin = it.json && it.binary ? it.binary : (it.binary || {});
const clave = Object.keys(bin)[0];
if (!clave) throw new Error('No llego ningun archivo de imagen');
const archivo = bin[clave];
const mime = archivo.mimeType || '';
if (!mime.startsWith('image/') && mime !== 'application/pdf' && mime !== 'application/octet-stream') {
  throw new Error('El archivo no es una imagen valida: ' + mime);
}

return [{ json: {
  origen: 'formulario',
  chat_id: '',
  maquina_hint: it.json['Maquina'] || '',   // la ROLLERA que eligio la persona
  planta: it.json['Planta'] || ''
}, binary: { data: archivo } }];

// Validaciones automaticas: nunca se guarda nada inventado.
// errores  -> bloquean la carga
// advertencias -> se guarda igual pero se avisa que revisar
const salida = $input.first().json;
let textoIA = salida.content?.parts?.[0]?.text ?? salida.text ?? '';
const limpio = textoIA.replace(/```json/gi, '').replace(/```/g, '').trim();
let d;
try {
  d = JSON.parse(limpio);
} catch (e) {
  throw new Error('La IA no devolvio un JSON valido: ' + textoIA.substring(0, 300));
}

const prep = $('Preparar').first().json;
const errores = [];
const adv = [];
const esIlegible = v => typeof v === 'string' && v.toUpperCase().includes('ILEGIBLE');

// --- fecha (obligatoria) ---
let fecha = d.fecha;
if (!fecha || esIlegible(fecha) || isNaN(new Date(fecha + 'T00:00:00').getTime())) {
  errores.push('Fecha faltante o ilegible: revisar la hoja');
  fecha = null;
} else {
  const f = new Date(fecha + 'T00:00:00');
  const dias = (Date.now() - f.getTime()) / 86400000;
  if (dias < -1) adv.push('La fecha es futura (' + fecha + '): verificar');
  if (dias > 60) adv.push('La fecha tiene mas de 60 dias (' + fecha + '): verificar');
}

// --- turno ---
let turno = String(d.turno || '').toLowerCase();
if (turno !== 'dia' && turno !== 'noche') {
  adv.push('Turno sin marcar o ilegible: se guarda como "dia", verificar');
  turno = 'dia';
}

// --- operario y maquina ---
let operario = (!d.operario || esIlegible(d.operario)) ? '' : String(d.operario).trim();
if (!operario) adv.push('Operario faltante o ilegible');
// La ROLLERA que corto la elige la persona al subir la hoja (campo Maquina del
// formulario). Es la maquina de la planta: define los kilos por maquina.
let rollera = String(prep.maquina_hint || '').trim();
if (!rollera) errores.push('Falta indicar en que rollera se corto: elegila al subir la hoja');

// Lo que dice la hoja en BOBINA DE MAQUINA es la extrusora que fabrico la bobina,
// no la rollera. Se guarda solo como dato de trazabilidad.
let maquina_origen = (d.maquina && !esIlegible(d.maquina)) ? String(d.maquina).trim() : '';
if (!maquina_origen) adv.push('Maquina de origen de la bobina faltante o ilegible');

// --- bobinas ---
const vistas = new Set();
const bobinas = [];
for (const b of (d.bobinas || [])) {
  const n = String(b.n_bobina || '').trim();
  if (!n || esIlegible(n)) { adv.push('Hay una fila de bobina sin numero legible: no se carga'); continue; }
  if (vistas.has(n)) { adv.push('Bobina repetida en la hoja: ' + n + ' (se carga una sola vez)'); continue; }
  vistas.add(n);

  let peso = Number(b.peso);
  if (!peso || isNaN(peso) || esIlegible(String(b.peso))) {
    peso = null;
    adv.push('Bobina ' + n + ': peso faltante o ilegible');
  } else if (peso < 10000 || peso > 100000) {
    adv.push('Bobina ' + n + ': peso fuera del rango habitual (' + peso + '), verificar');
  }

  let estado = String(b.estado || '').toUpperCase();
  if (estado !== 'BIEN' && estado !== 'MAL') {
    estado = null;
    adv.push('Bobina ' + n + ': estado BIEN/MAL sin marcar o ilegible');
  }

  bobinas.push({
    n_bobina: n,
    peso,
    iniciales: (b.iniciales && !esIlegible(b.iniciales)) ? String(b.iniciales).toUpperCase().trim() : '',
    estado,
    defecto: (b.defecto && !esIlegible(b.defecto)) ? String(b.defecto).trim() : ''
  });
}
if (bobinas.length === 0) errores.push('No se pudo leer ninguna bobina de la hoja');

// --- scrap ---
const se = Number(d.scrap_empalme);
const sr = Number(d.scrap_rollo);
if (d.scrap_empalme == null || isNaN(se)) adv.push('Scrap de empalme faltante o ilegible (se guarda 0)');
if (d.scrap_rollo == null || isNaN(sr)) adv.push('Scrap de rollo faltante o ilegible (se guarda 0)');

const datos = {
  empresa: 'Coop El Circulo',
  planta: prep.planta || 'Rolleras',
  rollera, maquina_origen, operario, fecha, turno, bobinas,
  scrap_empalme: isNaN(se) ? 0 : se,
  scrap_rollo: isNaN(sr) ? 0 : sr,
  medida: (d.medida && !esIlegible(d.medida)) ? d.medida : '',
  filas: Number(d.filas) || null,
  bultos: Number(d.bultos) || null,
  observaciones: (d.observaciones && !esIlegible(d.observaciones)) ? d.observaciones : '',
  origen: prep.origen
};

return [{ json: { datos, errores, advertencias: adv, chat_id: prep.chat_id } }];
